from __future__ import annotations

import json
from pathlib import Path

from .analysis import Inventory
from .scanner import CobolUnit


def write_inventory(inventory: Inventory, output: Path) -> None:
    output.mkdir(parents=True, exist_ok=True)
    (output / "inventory.json").write_text(json.dumps(inventory, indent=2) + "\n", encoding="utf-8")


def write_markdown(units: list[CobolUnit], inventory: Inventory, output: Path) -> None:
    metrics = inventory["metrics"]
    unresolved = inventory["unresolved"]

    lines = [
        "# COBOL Inventory",
        "",
        "> Generated by cobol-migration-toolkit. This is a discovery aid, not authoritative "
        "program semantics — regex extraction misses dynamic CALLs, embedded SQL/CICS, and "
        "vendor extensions.",
        "",
        "## Summary",
        "",
        f"- Units: **{metrics['unit_count']}** "
        f"({metrics['program_count']} programs, {metrics['copybook_count']} copybooks)",
        f"- CALL edges: {metrics['call_edges']} · COPY edges: {metrics['copy_edges']}",
        f"- Unresolved CALLs: {metrics['unresolved_call_count']} · "
        f"Unresolved copybooks: {metrics['unresolved_copybook_count']}",
        f"- Unreferenced programs (fan-in 0): {', '.join(metrics['unreferenced_programs']) or 'none'}",
        f"- Unreferenced copybooks: {', '.join(metrics['unreferenced_copybooks']) or 'none'}",
        "",
    ]

    replacing = metrics["copybooks_using_replacing"]
    if replacing:
        lines += [
            "> ⚠️ `COPY ... REPLACING` used for: "
            f"{', '.join(replacing)}. Expanded text differs from the raw copybook — "
            "review these manually.",
            "",
        ]

    if unresolved.get("copybooks") or unresolved.get("calls"):
        lines += ["## Unresolved dependencies", ""]
        if unresolved.get("copybooks"):
            lines.append(f"- Copybooks: {', '.join(unresolved['copybooks'])}")
        if unresolved.get("calls"):
            lines.append(f"- Static CALL targets: {', '.join(unresolved['calls'])}")
        lines.append("")

    lines += ["## Units", ""]
    for unit in units:
        lines.extend(
            [
                f"### `{unit.path}`",
                "",
                f"- Type: `{unit.kind}` · Format: `{unit.source_format}`",
                f"- Program ID: `{unit.program_id or 'unknown'}`",
                f"- Lines: {unit.line_count}",
                f"- COPY dependencies: {', '.join(unit.copybooks) or 'none'}"
                + (f" (REPLACING: {', '.join(unit.copy_replacing)})" if unit.copy_replacing else ""),
                f"- CALL targets: {', '.join(unit.calls) or 'none'}",
                f"- Paragraphs: {', '.join(unit.paragraphs) or 'none'}",
                "",
            ]
        )
    (output / "report.md").write_text("\n".join(lines), encoding="utf-8")


def write_dot(units: list[CobolUnit], inventory: Inventory, output: Path) -> None:
    unresolved = inventory["unresolved"]
    unresolved_calls = set(unresolved["calls"])
    unresolved_copybooks = set(unresolved["copybooks"])

    lines = ["digraph cobol_dependencies {", "  rankdir=LR;", "  node [shape=box];"]
    for unit in units:
        source = unit.program_id or unit.path
        for target in unit.calls:
            style = ' [label="CALL", color=red]' if target in unresolved_calls else ' [label="CALL"]'
            lines.append(f'  "{source}" -> "{target}"{style};')
        for target in unit.copybooks:
            attrs = 'label="COPY", style=dashed'
            if target in unresolved_copybooks:
                attrs += ", color=red"
            lines.append(f'  "{source}" -> "{target}" [{attrs}];')
    # Distinguish unresolved targets visually.
    for name in sorted(unresolved_calls | unresolved_copybooks):
        lines.append(f'  "{name}" [style=filled, fillcolor="#ffdddd"];')
    lines.append("}")
    (output / "dependencies.dot").write_text("\n".join(lines) + "\n", encoding="utf-8")
